async function huntAnimals() {
  // Cows and Chickens are usually north/west of Lumbridge
  // Trying to walk toward potential animal spawn areas
  await bot.walkTo(3210, 3210);

  const targets = ["Chicken", "Cow", "Zombie", "Giant rat"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 30000);
      killed.push(target);
    }
  }
  return killed;
}

return await huntAnimals();

